"""Report current local implementation, with separate API and isolated-demo evidence."""
from pathlib import Path
from reportlab.platypus import Spacer, Image, Table, TableStyle
from reportlab.lib.utils import ImageReader
def report_current(g):
    p,table,page,write_pdf,h=g['p'],g['table'],g['page'],g['write_pdf'],g['h']
    d=g['DATA'];out=g['OUT'];root=g['ROOT'];st=[];summary=d['summary']
    flow=d.get('currentFlow') or {};contrast=d.get('currentContrast') or {};api=d.get('apiDatabase') or {}
    cases=contrast.get('cases',[])
    def image(file,width=226,height=285):
        path=root/file
        if not path.is_file():return p('Captura pendiente de incorporar.','Small')
        iw,ih=ImageReader(str(path)).getSize();scale=min(width/iw,height/ih)
        return Image(str(path),width=iw*scale,height=ih*scale)
    page(st,'Accesibilidad de CONTIGO',[
      Spacer(1,20),p('Interfaz actual y auditoría parcial de accesibilidad','Title'),
      p('APF3 Interacción Hombre Máquina<br/>Caso Clínica San Pablo<br/>Versión local actual del 3 de noviembre de 2026'),Spacer(1,22),
      table([['Equipo','Sección'],['Julio Rodrigo Minaya Urdanivia\nAndres Benjamin Puma Parave\nGerson David Vega Cisneros','35145']],[350,131]),Spacer(1,24),
      p('Paciente: medicamentos y mediciones en una vista simplificada. Cuidador: tratamiento, existencias, citas y seguimiento. Integración local mediante API y PostgreSQL.'),
      p('La evidencia actual corresponde únicamente a evidence/current-2026-11-03. Se distinguen las lecturas sobre API/PostgreSQL de los cambios de datos sintéticos realizados en una demostración aislada.'),
      p('Estado: evaluación técnica parcial. Las sesiones con personas, la demostración Figma publicada y Stark permanecen pendientes según los registros disponibles. No se declara conformidad AA total.')])
    page(st,'1 Contexto alcance y objetivo',[
      p('El proyecto conserva Clínica San Pablo como caso académico del APF1 y APF2. La clínica se representa como origen de prescripciones, horarios y citas. El paciente declara sus tomas y registra lecturas de su equipo; el cuidador consulta el seguimiento y las existencias sin modificar la prescripción.'),
      p('La interfaz vigente simplifica /patient-app a una sola vista de medicamentos y mediciones. Se retiraron las pestañas inferiores, Ajustes y el acceso al dashboard desde el móvil. Las respuestas anteriores se revisan desde Tomas registradas hoy. El SOS de prueba conserva acceso superior y las opciones generales de lectura permanecen disponibles.'),
      table([['Rol','Alcance actual'],['Paciente','Medicamentos, respuesta/corrección, SOS de prueba y medición de presión/pulso o peso, con ingreso, revisión, corrección y guardado.'],['Cuidador','Resumen, tratamiento y existencias, citas, mediciones y ficha clínica. Las pantallas y estados efectivamente comprobados se enumeran en los JSON actuales.']],[90,391]),
      table([['Tarea','Cierre definido']]+[[t['id']+' '+t['role'],t['success']] for t in d['tasks']],[100,381]),
      p('Objetivo técnico: WCAG 2.1 AA, incluidos criterios A. Se registran 50 criterios y los 26 núcleo de la consigna. La simplificación no elimina T3: pertenece al cuidador. El tamaño 44 × 44 px se trata como buena práctica de 2.5.5 AAA, no como criterio AA.')])
    page(st,'2 Versión y metodología',[
      p('Este paquete describe la revisión actual simplificada y el formulario rediseñado. Las comprobaciones históricas por pestañas, el zoom nativo y los anuncios antiguos de NVDA se conservan por su versión. No se trasladan automáticamente a los archivos actuales. Los entregables anteriores están en history/2026-11-03-pre-current-refresh.'),
      table([['Condición','Qué acredita'],['API/PostgreSQL local, puerto 3001','Salud, acceso sintético por rol, lecturas autorizadas y aislamiento. No acredita escrituras clínicas ni despliegue público.'],['Demostración aislada, puerto 3013','Recorrido de teclado con datos sintéticos privados. T1 cambia solo el almacenamiento del contexto aislado; T2 cancela y T4 revisa sin guardar.'],['Contraste y geometría actual','Estilos calculados y contraste sRGB; ancho 320/390/430, escala de lectura 100/200 % y alto contraste. No es zoom nativo ni Stark.']],[155,326]),
      p('El APF2 aportado conserva ejemplos simulados: T1 4,65 s, T2 2,05 s y SUS 95,83. No son una línea base empírica ni resultados de participantes de esta versión. T3 vigente no tiene medición anterior comparable. Para comparar usabilidad deben ejecutarse las mismas metas por rol, caso y dispositivo.'),
      p('Método previsto: triangulación de herramientas automáticas, inspección manual y tecnología de apoyo. La matriz registra evidencia parcial y pendientes. Una sonda de contraste, un árbol accesible o una operación con teclas no demuestra comprensión de una persona ni el criterio WCAG completo.'),
      table([['Valor','Regla'],['Severidad S','1 mejora; 2 dificultad menor; 3 requiere ayuda/rodeo; 4 bloqueo de tarea para un perfil.'],['Alcance A','1 elemento; 2 varias vistas; 3 patrón global o flujo crítico.'],['Prioridad S × A','Alta ≥ 8, Media 4–7, Baja ≤ 3. Cerrar todas las altas y resolver o planificar al menos 70 % de medias.']],[110,371])])
    stats=[['Evidencia actual','Resultado registrado','Límite'],['axe por pantalla/estado',f"{summary['screens']} estados; {summary['violations']} incidencias de reglas; {summary['violationNodes']} nodos señalados. Incomplete: {summary['incomplete']} reglas y {summary['incompleteNodes']} nodos.",'Solo condiciones ejecutadas. Incomplete requiere revisión manual.'],['Teclado T1–T4',f"{sum(c.get('passed') is True for c in flow.get('checks',[]))} tareas aprobadas de {len(flow.get('checks',[]))} registradas.",'Datos sintéticos privados; sin participantes ni escrituras API.'],['Formulario presión y peso',f"{len(cases)} combinaciones de ancho/escala/contraste en registro de geometría.",'Escala del producto, no zoom nativo.'],['API y PostgreSQL',f"Registro {'completo' if api.get('complete') else 'pendiente'}; salud: {api.get('health',{}).get('storage','no registrada')}.",'Lecturas y sesiones de prueba; sin modificaciones clínicas.']]
    page(st,'3 Resultados de la auditoría técnica',[
      p('Los resultados proceden de los JSON conservados en el corte actual. Los conteos de herramientas no se presentan como métricas humanas ni como porcentaje de conformidad. La matriz desarrolla los 50 criterios por cada estado que dispone de evidencia.'),table(stats,[122,206,153]),
      p('Contraste del formulario: la revisión señaló límites aproximados de 2,72:1 en campos y 2,97:1 en selector. El ajuste usa #74887e: aproximadamente 3,62:1 frente al interior del campo y 3,77:1 frente al blanco. Los valores efectivos, estados y resultados de foco están en contrast/before.json y contrast/after.json; no acreditan todos los componentes de la aplicación.'),
      p('Se verifica que valores extremos de demostración como 500/499, pulso y peso 1000.0 quepan en su área útil, se puedan revisar y se conserven al volver. La revisión de todos los dígitos en cada combinación y sus capturas constituye evidencia geométrica limitada.'),
      p('La revisión complementaria de los 25 nodos incomplete de contraste obtuvo 18 cotas conservadoras suficientes y dejó 7 pendientes por limitaciones del método. No se eliminan ni reclasifican los 25 incomplete de axe como cumplimiento integral. Los registros y capturas se conservan en incomplete-contrast/results.json.'),
      p('El recorrido actual de T4 comprueba identificación del error, corrección y revisión, con retorno sin guardar. No se afirma que se haya probado guardar una lectura sobre PostgreSQL. La consulta T3 y las lecturas API se documentan separadas de los cambios privados de T1.'),
      p('Los hallazgos y prioridades expresan riesgo técnico estimado. Su cierre integral requiere la matriz manual y los perfiles afectados; la corrección de código y cero incidencias detectadas por una herramienta no bastan para cerrar todas las prioridades altas.')])
    for category,label in [('Sensorial','sensoriales'),('Motora','motores'),('Cognitiva','cognitivos')]:
      changes=[a for a in d['adjustments'] if a['category']==category]
      items=[table([['Ajuste y criterio','Implementación y comprobación residual']]+[[a['id']+' '+a['criteria'],a['change']+' '+a['verify']] for a in changes],[123,358])]
      if category=='Sensorial':
        before='output/apf3/evidence/current-2026-11-03/contrast/before-390-100-standard-digits.png'
        after='output/apf3/evidence/current-2026-11-03/contrast/after-390-100-standard-digits.png'
        items += [Table([[p('Antes del ajuste de límites','Small'),p('Después del ajuste de límites','Small')],[image(before),image(after)]],colWidths=[240,241]),p('Capturas locales del mismo formulario actual, antes y después de la corrección de contraste. Datos sintéticos; no son sesiones ni una comparación experimental APF2/APF3.','Caption')]
      elif category=='Cognitiva':
        a='output/apf3/evidence/current-2026-11-03/flows/03-t4-invalid.png';b='output/apf3/evidence/current-2026-11-03/presentation-measurement-review.png'
        items += [Table([[p('Error de entrada','Small'),p('Revisión de valores','Small')],[image(a),image(b)]],colWidths=[240,241]),p('Izquierda: error en demostración aislada con teclado. Derecha: captura nativa del formulario API actual con 120/80, sin guardar. Los registros distinguen ambos orígenes; no son sesiones con participantes.','Caption')]
      else:items += [p('Las capturas de flujos muestran el foco y las acciones ejecutadas por teclado. Las comprobaciones técnicas no equivalen a descubrimiento autónomo con un lector de pantalla. El formato móvil actual ya no tiene navegación por pestañas.'),p('Trazabilidad: tres ajustes por categoría, cada uno vinculado a criterio y archivos de implementación. Las comparaciones históricas se identifican como antecedentes y no se presentan como capturas de la versión actual.')]
      page(st,'4 Ajustes '+label,items)
    page(st,'5 Validación inclusiva pendiente',[
      p('No se aportan consentimientos ejecutados ni resultados humanos de esta versión. Las hojas Sesiones y SUS y los formularios permanecen preparados sin respuestas. No se calculan tiempos medios, éxito, SEQ ni SUS de participantes a partir de las pruebas de software.'),
      p('Se requieren al menos cinco participantes que cubran tres perfiles. Para Excelente en C3, al menos dos deben tener una condición real o usar habitualmente una tecnología de apoyo. Participar no exige revelar un diagnóstico. La simulación de una condición debe registrarse como tal.'),
      table([['Aspecto','Regla antes de ejecutar'],['Consentimiento','Explicar propósito, datos, conservación, responsable y retiro; autorización separada para grabar.'],['Versiones','Fijar código, caso y rol; alternar orden cuando las tareas sean equivalentes. No usar cifras simuladas como línea base observada.'],['Medición','Registrar tiempo, errores, ayuda, cierre o abandono. No mezclar fallos y éxitos en una media que sugiera mejora.'],['Cuestionarios','SEQ 1–7 tras cada tarea y SUS 10 ítems tras cada versión. No llenar ausencias con cero.'],['Barreras','Registrar criterio, perfil, evidencia y severidad; verificar con tecnología habitual de la persona.']],[105,376]),
      p('Metas exploratorias propuestas: éxito autónomo ≥ 80 % por tarea/perfil y SUS ≥ 68, fijadas antes de sesiones. No son resultados actuales ni límites clínicos. Los instrumentos incluyen T4 vigente y el paso de revisión. Las firmas originales se conservan en privado; los anexos públicos solo admiten copias anonimizadas.')])
    page(st,'6 Normativa y declaración parcial',[
      p('WCAG 2.1 AA es el objetivo técnico académico. La Ley 29973 y su reglamento sustentan el acceso a servicios y TIC; el artículo 23.2 contempla entidades privadas que prestan servicios web. La Ley 29733 y el Reglamento D.S.016-2024-JUS orientan el tratamiento de datos de las pruebas. No se certifica cumplimiento legal institucional de la clínica.'),
      p('La R.M.126-2009-PCM fue derogada por R.M.100-2025-PCM. El lineamiento R.SGTD001-2025-PCM/SGTD corresponde a la Administración Pública: se usa como contexto y se distingue del caso privado. La Convención ONU, arts.9 y21, aporta marco de derechos; Section508 se usa como benchmark federal estadounidense. ISO/IEC40500:2025 adopta WCAG2.2 sin cambiar el objetivo2.1 del curso.'),
      p('<b>Estado: evaluación técnica parcial, no Conforme AA.</b> Versión local simplificada y formulario rediseñado de 3 de noviembre de 2026. Métodos: pruebas actuales de teclado y contraste/geometría, inspección de fuente y lecturas API/PostgreSQL; solo las pantallas/estados efectivamente registrados en current-2026-11-03 forman parte del resultado técnico.'),
      table([['Principio','Criterios A/AA','Estado'],['Perceptible',20,'Parcial; contrastes y geometría actuales no cubren todos los criterios.'],['Operable',17,'Parcial; recorrido con teclas limitado a condiciones ejecutadas.'],['Comprensible',10,'Parcial; mensajes y revisión implementados, comprensión humana pendiente.'],['Robusto',3,'Parcial; comprobar salida del lector y estados remotos de la versión vigente.']],[112,100,269]),
      p('Figma: '+d['status']['figma']+' Stark: '+d['status']['stark']),
      p('Canal de barreras: GitHub Issues del proyecto, https://github.com/julio060606/HOMBRE-MAQUINA-APLIACION-CONTIGO/issues. Informar versión, pantalla, acción y tecnología usada, evitando información de salud o identidad. No se atribuye aprobación institucional al proyecto.')])
    page(st,'7 Conclusiones y plan de cierre',[
      p('La entrega canónica se actualiza para una sola revisión del repositorio correcto. La evidencia anterior permanece preservada como histórica. La simplificación del móvil, el formulario de medición y las correcciones de contraste tienen registros propios; las lecturas de la API central y PostgreSQL se distinguen de los cambios privados de demostración.'),
      table([['Pendiente','Condición de cierre'],['Auditoría integral','Evaluar 26 núcleo y justificar los restantes por pantalla; cerrar prioridades altas y documentar medias.'],['Tecnologías de apoyo','Completar lector, zoom nativo, orientación y espaciado sobre el código actual; no reutilizar automáticamente ensayos históricos.'],['Figma y Stark','Archivo nativo actual, seis páginas, kit, anotaciones, simulaciones y enlace de visualización probado.'],['Participantes','Cinco sesiones, tres perfiles, consentimiento y métricas por persona y versión.'],['Acceso público','Backend desplegado y URL frontend configurada; prueba completa en sesión nueva. La ejecución local no acredita Vercel.'],['Sustentación','Doce diapositivas, doce minutos de exposición y tres de preguntas; todos justifican decisiones y límites.']],[125,356]),
      p('Uso de IA: Codex y subagentes apoyaron código, inspección, documentación y ejecución de herramientas. No se generaron participantes, firmas, testimonios ni métricas humanas. El equipo debe revisar los contenidos y su contribución y respetar la política de IA del curso.')])
    for chunk in [d['sources'][:6],d['sources'][6:]]:
      page(st,'Referencias',sum(([p(g['clean'](s['title'])),p(g['clean'](s['url']),'Small'),p(g['clean'](s['use']),'Small')] for s in chunk),[]))
    return write_pdf('APF3_CONTIGO_Informe.pdf',st)
